import { createQueue, createDedup, createPump, createSink } from './src/index.js'

// --- G1: effectively-once ---
// m1's first attempt fails AFTER the sink recorded it; on retry it is emitted again.
{
  const queue = createQueue()
  const sink = createSink()
  let t = 0
  const clock = { now: () => t }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock,
    processMessage: () => ++calls === 1 ? false : true,
  })
  pump.run(10)
  t = 100
  pump.run(10)
  console.log('G1 delivered:', JSON.stringify(sink.deliveredIds()), 'duplicate:', sink.hasDuplicate())
}

// --- G2: per-key ordering across retries ---
// m1 (K) fails on first attempt and is retried after m2 (K) has been delivered.
{
  const queue = createQueue()
  const sink = createSink()
  let t = 0
  const clock = { now: () => t }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  let calls = 0
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock,
    processMessage: () => {
      calls += 1
      return calls !== 1 // m1 fails first, everything else succeeds
    },
  })
  pump.run(10)
  t = 100
  pump.run(10)
  console.log('G2 delivered:', JSON.stringify(sink.deliveredIds()))
}

/**
 * Delivery pump: dequeue → skip duplicates → deliver → ack + record, or requeue
 * with backoff on failure.
 *
 * Delivery guarantees (see README):
 *
 * - Effectively-once: the message id is recorded in the dedup guard and emitted
 *   to the sink on the FIRST delivery attempt, before the downstream is called.
 *   If that attempt fails, the message is requeued with backoff and the retry
 *   re-attempts the downstream WITHOUT emitting again — so even when an attempt
 *   fails after the downstream has already accepted the message, the id is
 *   delivered to the sink at most once. A duplicate id freshly enqueued into
 *   the queue is dropped without being delivered.
 *
 * - Per-key ordering: the sink records deliveries in first-attempt order, which
 *   follows FIFO enqueue order. Retries never emit, so an earlier same-key
 *   message is recorded before a later one even across retries.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  const handleFailure = (message) => {
    message.attempts += 1
    if (message.attempts >= maxAttempts) {
      queue.ack(message.id)
      sink.failed(message)
      return
    }
    message.retryAt = clock.now() + retryWithBackoff(clock).delayFor(message.attempts)
    queue.requeue(message)
  }
  return {
    run(steps = Infinity) {
      for (let i = 0; i < steps; i++) {
        const message = queue.dequeue()
        if (message === null) break
        if (message.retryAt !== undefined && clock.now() < message.retryAt) {
          queue.requeue(message)
          continue
        }
        if (dedup.isDuplicate(message.id, clock.now())) {
          if (message.retryAt !== undefined) {
            // Retry of an id already delivered to the sink: re-attempt the
            // downstream, but never emit a second delivery.
            dedup.record(message.id, clock.now())
            if (processMessage(message)) {
              queue.ack(message.id)
            } else {
              handleFailure(message)
            }
            continue
          }
          // Duplicate id fresh in the queue: never deliver it.
          queue.ack(message.id)
          continue
        }
        // First delivery attempt: guard and record before the downstream call.
        dedup.record(message.id, clock.now())
        sink.emit(message)
        if (processMessage(message)) {
          queue.ack(message.id)
        } else {
          handleFailure(message)
        }
      }
    },
  }
}

