import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink } from './src/index.js'

test('G1: retry after failed attempt never re-emits, but does re-process downstream', () => {
  const queue = createQueue()
  const sink = createSink()
  let t = 0
  const clock = { now: () => t }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock,
    processMessage: () => ++calls === 1 ? false : true,
  })
  pump.run(10)
  t = 100
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  assert.equal(calls, 2, 'downstream is re-attempted on retry')
  assert.deepEqual(queue.pending(), [])
})

test('G2: earlier same-key message stays before later ones across retries', () => {
  const queue = createQueue()
  const sink = createSink()
  let t = 0
  const clock = { now: () => t }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  queue.enqueue({ id: 'm3', key: 'K', payload: 3 })
  let calls = 0
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock,
    processMessage: () => {
      calls += 1
      return calls !== 1 && calls !== 3 // m1 first attempt and m2 first attempt fail
    },
  })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2', 'm3'], 'first-attempt order = enqueue order')
  t = 300
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2', 'm3'], 'retries never re-emit')
  assert.equal(sink.hasDuplicate(), false)
})

test('G1: abandonment after maxAttempts records failure, single emit', () => {
  const queue = createQueue()
  const sink = createSink()
  let t = 0
  const clock = { now: () => t }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock,
    processMessage: () => false,
    maxAttempts: 3,
  })
  pump.run(10)
  t = 100
  pump.run(10)
  t = 300
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  assert.deepEqual(queue.pending(), [])
})

test('fresh queue duplicate is dropped even while a retry of the same id is in flight', () => {
  const queue = createQueue()
  const sink = createSink()
  let t = 0
  const clock = { now: () => t }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock,
    processMessage: () => false,
    maxAttempts: 5,
  })
  pump.run(10) // m1 emitted, failed, requeued (retryAt = 100)
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 }) // producer re-enqueue
  t = 100
  pump.run(10) // retry re-processes; fresh duplicate dropped
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
})

test('downstream accepted but attempt failed: id delivered to sink exactly once', () => {
  const queue = createQueue()
  const sink = createSink()
  let t = 0
  const clock = { now: () => t }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  // m1: downstream accepted on attempt 1 but the attempt reports failure (ack lost)
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock,
    processMessage: (m) => m.id !== 'm1' || (t >= 100),
  })
  pump.run(10)
  t = 100
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
  assert.equal(sink.hasDuplicate(), false)
})
